    fun text(value: String): String {
        if (language == "fi") return value
        val index = when (language) { "ru" -> 0; "en" -> 1; "sv" -> 2; "et" -> 3; "lt" -> 4; "lv" -> 5; "nb" -> 6; "da" -> 7; "fr" -> 8; "es" -> 9; "it" -> 10; "de" -> 11; "pl" -> 12; else -> return value }
        return translations[value]?.getOrNull(index) ?: value
    }
